import Foundation
import SQLKit

/// Where audit_entries rows are kept. Services depend only on this protocol.
public protocol AuditEntryRepository: Sendable {
    /// The row with this primary key, or nil.
    func findByEntryNo(_ entryNo: Int) async throws -> AuditEntry?

    /// At most limit rows from offset, by primary key, and how many there are.
    func list(offset: Int, limit: Int) async throws -> Page<AuditEntry>

    /// Rows with this orderId, by primary key.
    func listByOrderId(_ orderId: Int) async throws -> [AuditEntry]

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: AuditEntry) async throws -> AuditEntry

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: AuditEntry) async throws -> AuditEntry

    /// Removes a row.
    func delete(_ entity: AuditEntry) async throws
}

/// Keeps audit_entries rows in the database, through SQLKit: on the database of the unit of work, or on its transaction.
public struct SqlAuditEntryRepository: AuditEntryRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findByEntryNo(_ entryNo: Int) async throws -> AuditEntry? {
        try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM \"audit_entries\" WHERE \"entry_no\" = \(bind: entryNo)").first().map(toEntity)
    }

    public func list(offset: Int, limit: Int) async throws -> Page<AuditEntry> {
        let total = try await database.sql.raw("SELECT COUNT(*) AS total FROM \"audit_entries\"").first()?.decode(column: "total", as: Int.self) ?? 0
        let items = try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM \"audit_entries\" ORDER BY \"entry_no\" LIMIT \(bind: limit) OFFSET \(bind: offset)").all().map(toEntity)
        return Page(items: items, total: total, offset: offset, limit: limit)
    }

    public func listByOrderId(_ orderId: Int) async throws -> [AuditEntry] {
        try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM \"audit_entries\" WHERE \"orderId\" = \(bind: orderId) ORDER BY \"entry_no\"").all().map(toEntity)
    }

    @discardableResult
    public func insert(_ entity: AuditEntry) async throws -> AuditEntry {
        var names: [String] = []
        var values: [any SQLExpression] = []
        if let value = entity.entryNo { names.append("\"entry_no\""); values.append(SQLQueryString("\(bind: value)")) }
        if let value = entity.orderId { names.append("\"orderId\""); values.append(SQLQueryString("\(bind: value)")) }
        if let value = entity.message { names.append("\"message\""); values.append(SQLQueryString("\(bind: value)")) }
        let insert: SQLQueryString =
            names.isEmpty ? "INSERT INTO \"audit_entries\" DEFAULT VALUES"
            : "INSERT INTO \"audit_entries\" (\(unsafeRaw: names.joined(separator: ", "))) VALUES (\(SQLList(values)))"
        let row = try await write { try await database.sql.raw("\(insert) RETURNING \(unsafeRaw: columns)").first() }
        return try row.map(toEntity) ?? entity
    }

    @discardableResult
    public func update(_ entity: AuditEntry) async throws -> AuditEntry {
        try await write { try await database.sql.raw("UPDATE \"audit_entries\" SET \"orderId\" = \(bound(entity.orderId)), \"message\" = \(bound(entity.message)) WHERE \"entry_no\" = \(bind: entity.entryNo!)").run() }
        return try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM \"audit_entries\" WHERE \"entry_no\" = \(bind: entity.entryNo!)").first().map(toEntity) ?? entity
    }

    public func delete(_ entity: AuditEntry) async throws {
        try await write { try await database.sql.raw("DELETE FROM \"audit_entries\" WHERE \"entry_no\" = \(bind: entity.entryNo!)").run() }
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "AuditEntry", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

/// The columns every read selects.
fileprivate let columns = "\"entry_no\", \"orderId\", \"message\""

fileprivate func toEntity(_ row: any SQLRow) throws -> AuditEntry {
    AuditEntry(
        entryNo: try row.optional("entry_no", as: Int.self),
        orderId: try row.optional("orderId", as: Int.self),
        message: try row.optional("message", as: String.self)
    )
}

/// Keeps audit_entries rows in memory, for tests and for trying the services without a database.
public final class MemoryAuditEntryRepository: AuditEntryRepository {
    private let rows = MemoryRows<AuditEntry>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [AuditEntry] {
        await rows.all.sorted(by: isBefore)
    }

    public func findByEntryNo(_ entryNo: Int) async throws -> AuditEntry? {
        await visible().first { $0.entryNo == entryNo }
    }

    public func list(offset: Int, limit: Int) async throws -> Page<AuditEntry> {
        let rows = await visible()
        return Page(items: Array(rows.dropFirst(offset).prefix(limit)), total: rows.count, offset: offset, limit: limit)
    }

    public func listByOrderId(_ orderId: Int) async throws -> [AuditEntry] {
        await visible().filter { $0.orderId == orderId }
    }

    @discardableResult
    public func insert(_ entity: AuditEntry) async throws -> AuditEntry {
        var entity = entity
        if entity.entryNo == nil { entity.entryNo = await rows.nextId() }
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    public func update(_ entity: AuditEntry) async throws -> AuditEntry {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    public func delete(_ entity: AuditEntry) async throws {
        await rows.remove { sameKey($0, entity) }
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: AuditEntry, _ b: AuditEntry) -> Bool {
    a.entryNo == b.entryNo
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: AuditEntry, _ b: AuditEntry) -> Bool {
    return less(a.entryNo, b.entryNo)
}

