    }

    public func findByCodeAndDay(_ code: String, _ day: Date) async throws -> Kind? {
        try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM \"kinds\" WHERE \"code\" = \(bind: code) AND \"day\" = \(bind: sqlText(day, day: true))").first().map(toEntity)
    }

    public func list(offset: Int, limit: Int) async throws -> Page<Kind> {
