        let items = try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM \"kinds\" ORDER BY \"code\", \"day\" LIMIT \(bind: limit) OFFSET \(bind: offset)").all().map(toEntity)
        return Page(items: items, total: total, offset: offset, limit: limit)
    }

    @discardableResult
    public func insert(_ entity: Kind) async throws -> Kind {
