import Foundation

/// The values of a AuditEntry that change: fields left .absent keep their value; .set(nil) empties one.
public struct AuditEntryChanges: Sendable {
    public var orderId: Patch<Int?>
    public var message: Patch<String?>

    public init(orderId: Patch<Int?> = .absent, message: Patch<String?> = .absent) {
        self.orderId = orderId
        self.message = message
    }
}

import Foundation

/// Operations on audit_entries. Each write runs in its own transaction.
public struct AuditEntryService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new AuditEntry after checking it.
    @discardableResult
    public func createAuditEntry(_ auditEntry: AuditEntry) async throws -> AuditEntry {
        let values = Values(orderId: auditEntry.orderId.map(Optional.some), message: auditEntry.message.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = AuditEntry()
            applyValues(&entity, values)
            return try await uow.auditEntries.insert(entity)
        }
    }

    /// The AuditEntry with this key; notFound when there is none.
    public func getAuditEntry(_ entryNo: Int) async throws -> AuditEntry {
        try await find(unitOfWork, entryNo)
    }

    /// A page of audit_entries, by primary key.
    public func listAuditEntries(offset: Int, limit: Int) async throws -> Page<AuditEntry> {
        try await unitOfWork.auditEntries.list(offset: offset, limit: limit)
    }

    /// Changes the given values of a AuditEntry.
    @discardableResult
    public func updateAuditEntry(_ entryNo: Int, _ changes: AuditEntryChanges) async throws -> AuditEntry {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, entryNo)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await uow.auditEntries.update(current)
        }
    }

    /// Deletes a AuditEntry.
    public func deleteAuditEntry(_ entryNo: Int) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, entryNo)
            try await uow.auditEntries.delete(current)
        }
    }

    /// The audit_entries with this orderId.
    public func listAuditEntriesByOrderId(_ orderId: Int) async throws -> [AuditEntry] {
        try await unitOfWork.auditEntries.listByOrderId(orderId)
    }
