import Foundation
import SQLKit
import SQLiteKit
import Testing
@testable import SwiftSqlDdlSqlite

/// Every test is in this suite, one after another: they all empty the same database.
@Suite(.serialized) struct DataTests {}

/// The test database: TEST_DATABASE_URL, or SQLite in memory, created again before every test.
enum TestDatabase {
    /// Runs body with the repositories over the test database, with every table dropped and created again first.
    static func with(_ body: (SqlUnitOfWork) async throws -> Void) async throws {
        let url = ProcessInfo.processInfo.environment["TEST_DATABASE_URL"]
        let app = if let url { AppDatabase(url: url) } else { AppDatabase(configuration: SQLiteConfiguration(storage: .memory)) }
        do {
            try await recreate(app.database)
            try await body(SqlUnitOfWork(db: app.database))
        } catch {
            await app.shutdown()
            throw error
        }
        await app.shutdown()
    }

    /// Drops every table and creates them again; on one connection, as MySQL turns its foreign key checks off for the connection that asks.
    private static func recreate(_ db: Db) async throws {
        try await db.sql.withSession { session in
            for statement in drop + create { try await session.raw("\(unsafeRaw: statement)").run() }
        }
    }

    /// Removes every table, so the database starts empty.
    private static let drop: [String] = [
        "DROP TABLE IF EXISTS \"empties\"",
        "DROP TABLE IF EXISTS \"audit_entries\"",
        "DROP TABLE IF EXISTS \"Order\"",
        "DROP TABLE IF EXISTS \"kinds\"",
        "DROP TABLE IF EXISTS \"things\"",
    ]

    /// Creates every table, in an order the database accepts.
    private static let create: [String] = [
        "CREATE TABLE \"things\" (\n  \"id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"small\" smallint NOT NULL,\n  \"big\" bigint NOT NULL,\n  \"price\" numeric(10,2) NOT NULL,\n  \"d\" real NOT NULL,\n  \"flag\" boolean NOT NULL DEFAULT TRUE,\n  \"born\" date NOT NULL,\n  \"opens\" time NOT NULL,\n  \"at\" datetime NOT NULL,\n  \"changed\" timestamp DEFAULT CURRENT_TIMESTAMP,\n  \"bin\" blob NOT NULL,\n  \"data\" json,\n  \"code\" char(5) NOT NULL,\n  \"note\" text,\n  \"total\" numeric(12,2) GENERATED ALWAYS AS (price * 2) STORED\n)",
        "CREATE TABLE \"kinds\" (\n  \"code\" varchar(10) NOT NULL,\n  \"day\" date NOT NULL,\n  \"label\" varchar(30),\n  PRIMARY KEY (\"code\", \"day\")\n)",
        "CREATE TABLE \"Order\" (\n  \"Id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"user\" varchar(40) NOT NULL,\n  \"group\" integer NOT NULL DEFAULT 0,\n  \"customerName\" varchar(60) NOT NULL,\n  \"class\" text,\n  \"metadata\" text,\n  \"date\" date,\n  \"time\" time,\n  \"text\" varchar(20),\n  \"list\" text,\n  \"str\" varchar(10),\n  \"int\" integer,\n  \"dueDate\" date NOT NULL,\n  \"closesAt\" time,\n  \"createdAt\" datetime DEFAULT CURRENT_TIMESTAMP,\n  \"kind_code\" varchar(10),\n  \"kind_day\" date,\n  \"thing_id\" integer,\n  \"parentId\" integer,\n  UNIQUE (\"customerName\"),\n  CHECK (\"group\" >= 0),\n  FOREIGN KEY (\"thing_id\") REFERENCES \"things\" (\"id\") ON DELETE SET NULL,\n  FOREIGN KEY (\"parentId\") REFERENCES \"Order\" (\"Id\"),\n  FOREIGN KEY (\"kind_code\", \"kind_day\") REFERENCES \"kinds\" (\"code\", \"day\")\n)",
        "CREATE TABLE \"audit_entries\" (\n  \"entry_no\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"orderId\" integer NOT NULL,\n  \"message\" varchar(200) NOT NULL,\n  FOREIGN KEY (\"orderId\") REFERENCES \"Order\" (\"Id\") ON DELETE CASCADE\n)",
        "CREATE TABLE \"empties\" (\n  \"id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"note\" text\n)",
    ]
}

/// The DomainError work throws, or nil when it throws none.
func refusal<T>(_ work: () async throws -> T) async -> DomainError? {
    do {
        _ = try await work()
        return nil
    } catch let error as DomainError {
        return error
    } catch {
        return nil
    }
}

func isConflict(_ error: DomainError?) -> Bool {
    if case .some(.conflict) = error { true } else { false }
}

func isNotFound(_ error: DomainError?) -> Bool {
    if case .some(.notFound) = error { true } else { false }
}

