import Foundation
import Testing
@testable import SwiftSqlDdlSqlite

extension DataTests {
    /// The service of the "things" table, on the in-memory repositories.
    @Suite struct ThingServiceTests {

        @Test func createsAValidRow() async throws {
            let uow = MemoryUnitOfWork()
            let service = ThingService(unitOfWork: uow)
            let row = Factories.newThing(1)
            let created = try await service.createThing(row)
            let found = try await service.getThing(created.id!)
            #expect(created.id == found.id)
        }

        @Test func refusesAMissingValue() async throws {
            let uow = MemoryUnitOfWork()
            let service = ThingService(unitOfWork: uow)
            var row = Factories.newThing(1)
            row.small = nil
            let error = await refusal { try await service.createThing(row) }
            #expect(error?.invalidFields == ["small"])
        }

        @Test func saysWhenARowIsMissing() async throws {
            let uow = MemoryUnitOfWork()
            let service = ThingService(unitOfWork: uow)
            #expect(isNotFound(await refusal { try await service.getThing(999999) }))
        }

        @Test func changesARow() async throws {
            let uow = MemoryUnitOfWork()
            let service = ThingService(unitOfWork: uow)
            let row = Factories.newThing(1)
            let created = try await service.createThing(row)
            let updated = try await service.updateThing(created.id!, ThingChanges(note: .set("changed")))
            #expect(updated.note == "changed")
        }

        @Test func deletesARow() async throws {
            let uow = MemoryUnitOfWork()
            let service = ThingService(unitOfWork: uow)
            let row = Factories.newThing(1)
            let created = try await service.createThing(row)
            try await service.deleteThing(created.id!)
            #expect(isNotFound(await refusal { try await service.getThing(created.id!) }))
        }
    }
}

